//! Binary-discovered threetched methods owned by one sealed plugin contract.
//!
//! The binary supplies command words, flags and token schemas. This plugin owns
//! admission policy; help text cannot establish that a command is read-only.
//! opblob is the sole sealer. Filesystem and transport consumers project its
//! sealed declarations and dispatch through the existing MutationEngine gate.

use std::fs::File;
use std::io::Read;
use std::path::Path;
use std::process::Command;
use std::sync::{Arc, OnceLock, atomic::{AtomicBool, Ordering}};

use anyhow::{Context, Result, bail, ensure};
use async_trait::async_trait;
use op_state::{ApplyResult, Checkpoint, DiffMetadata, PluginCapabilities, StateDiff, StatePlugin};
use op_state_store::method_receipt::UnsupportedBeforeEffect;
use op_state_store::{CapabilityDecl, MethodDecl, PluginSchema, SideEffect};
use schemars::JsonSchema;
use serde::{Deserialize, Serialize};
use serde_json::Value;
use sha2::{Digest, Sha256};
use simd_json::OwnedValue;
use tched_fs::threetched_surface::{SurfaceSnapshot, ThreetchedSurface};

pub const PLUGIN_NAME: &str = "threetched";
const VERSION: &str = "1.0.0";
const MANIFEST_FORMAT: &str = "opdbus.threetched.v2";

/// Immutable discovery evidence, never a copy of the running configuration.
/// Capture selectors are build/seal inputs; these paths select the installed
/// runtime and stay identical when the candidate is staged into a release.
#[derive(Debug, Clone, Serialize, Deserialize, JsonSchema)]
#[serde(deny_unknown_fields)]
pub struct ThreetchedState {
    pub binary: String,
    pub manifest: String,
    pub config_dir: String,
    pub binary_sha256: String,
    pub manifest_sha256: String,
    pub surface: Value,
}

struct Captured {
    state: ThreetchedState,
    surface: ThreetchedSurface,
    version: String,
}

static CAPTURED: OnceLock<std::result::Result<Captured, String>> = OnceLock::new();

/// Explicit authoring entry point for opblob and generated bridge contracts.
/// Each opblob command is a new process: every seal captures fresh bytes, shared
/// by all consumers in that invocation. Runtime never initializes this cache.
pub fn prepare_schema_capture() -> Result<()> {
    CAPTURED.get_or_init(|| capture().map_err(|error| format!("{error:#}")))
        .as_ref().map(|_| ()).map_err(|error| anyhow::anyhow!("{error}"))
}

pub(crate) fn is_schema_capture() -> bool {
    CAPTURED.get().is_some()
}

#!/bin/sh
set -eu

package_dir=$(CDPATH= cd -- "$(dirname -- "$0")" && pwd)
. "$package_dir/source.pin"
source_pin_sha256=$(sha256sum "$package_dir/source.pin" | awk '{print $1}')

output_dir=target/threetched-artifacts/tched-router
cache_dir=
source_dir=
source_archive=
verify_source_only=0

usage() {
    cat >&2 <<'EOF'
usage: build-threetched.sh --cache-dir DIR [--output-dir DIR]
       build-threetched.sh --cache-dir DIR --source-dir CLEAN-GIT-DIR [--output-dir DIR]
       build-threetched.sh --cache-dir DIR --source-archive PINNED-TAR [--output-dir DIR]

Builds the pinned, patched tched-router threetched dependency. It writes only the
cache, Cargo target directory and output directory; it never installs a binary.
With no explicit source option it prefers the checked-in source.tar.gz, then a
verified cache entry, and only then the exact upstream tag. --verify-source-only
stops after materializing and verifying the deterministic source tar.
EOF
    exit 2
}

while [ "$#" -gt 0 ]; do
    case "$1" in
        --cache-dir) [ "$#" -ge 2 ] || usage; cache_dir=$2; shift 2 ;;
        --output-dir) [ "$#" -ge 2 ] || usage; output_dir=$2; shift 2 ;;
        --source-dir) [ "$#" -ge 2 ] || usage; source_dir=$2; shift 2 ;;
        --source-archive) [ "$#" -ge 2 ] || usage; source_archive=$2; shift 2 ;;
        --verify-source-only) verify_source_only=1; shift ;;
        -h|--help) usage ;;
        *) usage ;;
    esac
done

[ -n "$cache_dir" ] || usage
[ -z "$source_dir" ] || [ -z "$source_archive" ] || {
    echo "choose only one of --source-dir and --source-archive" >&2
    exit 2
}
for command_name in awk cargo git grep gzip install jq patch rustc sha256sum strings tar; do
    command -v "$command_name" >/dev/null 2>&1 || {
        echo "missing threetched build command: $command_name" >&2
…
    }
done

